Request Payment.code:
// Ask a payer to approve a payment on their phone.
request(
  // 1) HTTP method.
  'POST',
  // 2) Path, relative to the baseUrl in your credential.
  '/collection/v1_0/requesttopay',
  // 3) The RequestToPay body.
  {
    amount: String($.data.amount),
    currency: 'UGX',
    // Your own reference for reconciliation.
    externalId: $.data.invoiceNumber,
    payer: { partyIdType: 'MSISDN', partyId: $.data.phoneNumber },
    payerMessage: 'Clinic consultation fee',
    payeeNote: `Invoice ${$.data.invoiceNumber}`,
  },
  // 4) Options: target environment and a UUID to track this request.
  {
    headers: {
      'X-Target-Environment': 'sandbox',
      'X-Reference-Id': $.data.referenceId,
    },
  }
);

Disburse Funds.code:
// Send a cash transfer to a beneficiary.
request(
  // 1) HTTP method.
  'POST',
  // 2) Disbursement transfer endpoint.
  '/disbursement/v1_0/transfer',
  // 3) The Transfer body.
  {
    amount: String($.data.amount),
    currency: 'UGX',
    externalId: $.data.paymentId,
    payee: { partyIdType: 'MSISDN', partyId: $.data.phoneNumber },
    payerMessage: 'Monthly cash transfer',
    payeeNote: `Household ${$.data.householdId}`,
  },
  // 4) Options: target environment and a UUID to track this transfer.
  {
    headers: {
      'X-Target-Environment': 'sandbox',
      'X-Reference-Id': $.data.referenceId,
    },
  }
);

Create Invoice.code:
// Create an invoice for a payer.
request(
  'POST',
  '/collection/v2_0/invoice',
  {
    externalId: $.data.invoiceNumber,
    amount: String($.data.amount),
    currency: 'UGX',
    // Seconds the invoice stays valid.
    validityDuration: '86400',
    intendedPayer: { partyIdType: 'MSISDN', partyId: $.data.phoneNumber },
    description: 'Community health insurance premium',
  },
  {
    headers: {
      'X-Target-Environment': 'sandbox',
      'X-Reference-Id': $.data.referenceId,
    },
  }
);

Get Payment Request Status.code:
// Check the status of an earlier request-to-pay.
request(
  'GET',
  // The X-Reference-Id used when the payment was requested.
  `/collection/v1_0/requesttopay/${$.data.referenceId}`,
  {},
  { headers: { 'X-Target-Environment': 'sandbox' } }
);

Get Transfer Status.code:
// Check the status of an earlier transfer.
request(
  'GET',
  // The X-Reference-Id used when the transfer was made.
  `/disbursement/v1_0/transfer/${$.data.referenceId}`,
  {},
  { headers: { 'X-Target-Environment': 'sandbox' } }
);

Check Account Is Active.code:
// Validate that a beneficiary's number has an active MoMo wallet.
request(
  'GET',
  `/collection/v1_0/accountholder/msisdn/${$.data.phoneNumber}/active`,
  {},
  { headers: { 'X-Target-Environment': 'sandbox' } }
);

Get Account Holder Info.code:
// Look up the registered name for a phone number.
request(
  'GET',
  `/collection/v1_0/accountholder/msisdn/${$.data.phoneNumber}/basicuserinfo`,
  {},
  { headers: { 'X-Target-Environment': 'sandbox' } }
);

Get Collection Balance.code:
// Get the collection account balance.
request(
  'GET',
  '/collection/v1_0/account/balance',
  {},
  { headers: { 'X-Target-Environment': 'sandbox' } }
);
